<?php
function render_custom_block( $attributes, $content, $block ) {
  $image_url = $attributes['image'];
  $heading = $attributes['heading'];
  $paragraph = $attributes['paragraph'];

  $image = wp_get_attachment_image( $image_url, 'full' );
  $heading_html = '<h2>' . $heading . '</h2>';
  $paragraph_html = '<p>' . $paragraph . '</p>';

  return '<div class="custom-block">' . $image . $heading_html . $paragraph_html . '</div>';
}
